    }

    function _run(uint256 dummy) internal {
        vm.assume(dummy == dummy);
        address owner1;
        try c.owner() returns (address __r) { owner1 = __r; } catch { return; }
        address owner2;
        try c.owner() returns (address __r) { owner2 = __r; } catch { return; }
        assertTrue(owner1 == owner2);
    }

    function testFuzz_run(uint256 dummy) public {
